    protected void createGenModelAnnotations() {
        String source = "http://www.eclipse.org/emf/2002/GenModel";
        this.addAnnotation((ENamedElement)this, source, new String[]{"documentation", "This package collects primitive types."});
        this.addAnnotation((ENamedElement)this.addressEDataType, source, new String[]{"documentation", "This is used to specify an address within the CPU. "});
        this.addAnnotation((ENamedElement)this.alignmentTypeEDataType, source, new String[]{"documentation", "This primitive represents the alignment of objects within a memory section. The value is in number of bits or UNKNOWN (deprecated), 8 , 16, 32 UNSPECIFIED or BOOLEAN. Typical values for numbers are 8, 16, 32."});
        this.addAnnotation((ENamedElement)this.booleanEDataType, source, new String[]{"documentation", "A Boolean value denotes a logical condition that is either 'true' or 'false'.\r\nIt can be one of \"0\", \"1\", \"true\", \"false\""});
        this.addAnnotation((ENamedElement)this.byteOrderEnumEEnum, source, new String[]{"documentation", "When more than one byte is stored in the memory the order of those bytes may differ depending on the architecture of the processing unit. If the least significant byte is stored at the lowest address, this architecture is called little endian and otherwise it is called big endian.\r\n\r\nByteOrder is very important in case of communication between different PUs or ECUs."});
        this.addAnnotation((ENamedElement)this.byteOrderEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "Most significant byte shall come at the lowest address (also known as BigEndian or as Motorola-Format)\r\n"});
        this.addAnnotation((ENamedElement)this.byteOrderEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "Most significant byte shall come highest address (also known as LittleEndian or as Intel-Format)\r\n"});
        this.addAnnotation((ENamedElement)this.byteOrderEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "For opaque data endianness conversion has to be configured to Opaque. See AUTOSAR COM Specification for more details."});
        this.addAnnotation((ENamedElement)this.categoryStringEDataType, source, new String[]{"documentation", "This represents the pattern applicable to categories.\r\n\r\nIt is basically the same as Identifier but has a different semantics. Therefore it is modeled as a primitive of its own.\r\n"});
        this.addAnnotation((ENamedElement)this.stringEDataType, source, new String[]{"documentation", "This represents a String in which white-space must be normalized before processing. For example: in order to compare two Strings:\r\n\r\n* leading and trailing white-space needs to be removed\r\n* consecutive white-space (blank, cr, lf, tab) needs to be replaced by one blank."});
        this.addAnnotation((ENamedElement)this.dateTimeEDataType, source, new String[]{"documentation", "A datatype representing a timestamp. The smallest granularity is 1 second.\r\n\r\nThis datatype represents a timestamp in the format yyyy-mm-dd followed by an optional time. The lead-in character for the time is \"T\" and the format is hh:mm:ss. In addition, a time zone designator must be specified. The time zone designator can either be \"Z\" (for UTC) or the time offset to UTC, i.e. (+|-)hh:mm.\r\n\r\nExamples:\r\n\r\n2009-07-23\r\n\r\n2009-07-23T14:38:00+01:00\r\n\r\n2009-07-23T13:38:00Z"});
        this.addAnnotation((ENamedElement)this.floatEDataType, source, new String[]{"documentation", "An instance of Float is an element from the set of real numbers. The value must comply with IEEE 754 and is limited to what can be expressed by a 64 bit binary representation."});
        this.addAnnotation((ENamedElement)this.integerEDataType, source, new String[]{"documentation", "An instance of Integer is an element in the set of integer numbers ( ..., -2, -1, 0, 1, 2, ...).  \r\n\r\nThe value can be expressed in decimal, octal, hexadecimal and binary representation. Negative numbers can only be expressed in decimal notation\r\n\r\nRange is from -2147483648 and 2147483647. \r\n"});
        this.addAnnotation((ENamedElement)this.mimeTypeStringEDataType, source, new String[]{"documentation", "This primitive denotes the an Internet media type, originally called a MIME type after MIME and sometimes a Content-type after the name of a header in several protocols whose value is such a type, is a two-part identifier for file formats on the Internet."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum, source, new String[]{"documentation", "This enumerator denotes the values for specification of  monotony for e.g. curves."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "This indicates that the related curve needs to be monotony increasing."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "This indicates that the related curve needs to be monotony decreasing."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "This indicates that the related curve needs to be strictly monotony increasing."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum.getELiterals().get(3), source, new String[]{"documentation", "This indicates that the related curve needs to be strictly monotony decreasing."});
        this.addAnnotation((ENamedElement)this.monotonyEnumEEnum.getELiterals().get(4), source, new String[]{"documentation", "This indicates that the related curve needs not to be monotony."});
        this.addAnnotation((ENamedElement)this.nameTokenEDataType, source, new String[]{"documentation", "This is an identifier as used in xml, e.g. xml-names. Basic difference to Identifier is the fact that it can contain \"-\"."});
        this.addAnnotation((ENamedElement)this.nativeDeclarationStringEDataType, source, new String[]{"documentation", "This string contains a native data declaration of a data type in a programming language. It is basically a string, but white-space must be preserved."});
        this.addAnnotation((ENamedElement)this.numericalEDataType, source, new String[]{"documentation", "This primitive specifies a numerical value. It can be denoted in different formats such as Decimal, Octal, Hexadecimal, Float. See the xsd pattern for details.\r\n"});
        this.addAnnotation((ENamedElement)this.positiveIntegerEDataType, source, new String[]{"documentation", "This is a positive integer which can be denoted in Decimal, octal and hexadecimal.\r\nthe value is between 0 and 4294967295.\r\n"});
        this.addAnnotation((ENamedElement)this.regularExpressionEDataType, source, new String[]{"documentation", "This is a regular expression as defined in \r\n\r\nhttp://www.w3.org/TR/xmlschema-2\r\n\r\nAs of now it is still produced as a string in XSD."});
        this.addAnnotation((ENamedElement)this.revisionLabelStringEDataType, source, new String[]{"documentation", "This primitive represents a revision label which identifies an engineering object. It represents a pattern which \r\n\r\n* requires three integers representing from left to right MajorVersion, MinorVersion, PatchVersion.\r\n\r\n* may add an application specific suffix separated by one of \".\", \"_\", \";\".\r\n\r\nLegal patterns are for example:\r\n\r\n4.0.0\r\n4.0.0.1234565\r\n4.0.0_vendor specific;13\r\n4.0.0;12\r\n"});
        this.addAnnotation((ENamedElement)this.sectionInitializationPolicyTypeEDataType, source, new String[]{"documentation", "SectionInitializationPolicyType describes the intended initialization of MemorySections. \r\nThe following values are standardized in AUTOSAR Methodology:\r\n\r\n* '''NO-INIT''': No initialization and no clearing is performed. Such data elements must not be read before one has written a value into it.\r\n* '''INIT''': To be used for data that are initialized by every reset to the specified value (initValue). \r\n* '''POWER-ON-INIT''': To be used for data that are initialized by \"Power On\" to the specified value (initValue). Note: there might be several resets between power on resets. \r\n* '''CLEARED''': To be used for data that are initialized by every reset to zero. \r\n* '''POWER-ON-CLEARED''': To be used for data that are initialized by \"Power On\" to zero. Note: there might be several resets between power on resets.\r\n\r\nPlease note that the values are defined similar to the representation of enumeration types in the XML schema to ensure backward compatibility."});
        this.addAnnotation((ENamedElement)this.timeValueEDataType, source, new String[]{"documentation", "This primitive type is taken for expressing time values. The numerical value is supposed to be interpreted in the physical unit second."});
        this.addAnnotation((ENamedElement)this.unlimitedIntegerEDataType, source, new String[]{"documentation", "An instance of UnlimitedInteger is an element in the set of integer numbers ( ..., -2, -1, 0, 1, 2, ...). \r\n\r\nThe range is limited by constraint 2534.\r\n\r\nThe value can be expressed in decimal, octal, hexadecimal and binary representation. Negative numbers can only be expressed in decimal notation.\r\n"});
        this.addAnnotation((ENamedElement)this.uriStringEDataType, source, new String[]{"documentation", "A Uniform Resource Identifier (URI), is a compact string of characters used to identify or name a resource."});
        this.addAnnotation((ENamedElement)this.verbatimStringEDataType, source, new String[]{"documentation", "This primitive represents a string in which white-space needs to be preserved."});
        this.addAnnotation((ENamedElement)this.displayFormatStringEDataType, source, new String[]{"documentation", "This is a display format specifier for the display of values  e.g. in documents or in measurement and calibration systems. \r\n\r\nThe display format specifier is a subset of the ANSI C printf specifiers with the following\r\nform:\r\n\r\n  % [flags] [width] [.prec] type character \r\n\r\nFor more details refer to \"ASAM-HarmonizedDataObjects-V1.1.pdf\" chapter 13.3.2 DISPLAY OF DATA. \r\n\r\nDue to the numerical nature of value settings, only the following type characters are allowed:\r\n\r\n* d:  Signed decimal integer \r\n* i:  Signed decimal integer \r\n* o:  Unsigned octal integer \r\n* u:  Unsigned decimal integer \r\n* x:  Unsigned hexadecimal integer, using \"abcdef\" \r\n* X:  Unsigned hexadecimal integer, using \"ABCDEF\" \r\n* e:  Signed value having the form [-]d.dddd e [sign]ddd where d is a single decimal digit, dddd is one or more decimal digits, ddd is exactly three decimal digits, and sign is + or - \r\n* E:  Identical to the e format except that E rather than e introduces the exponent \r\n* f:  Signed value having the form [-]dddd.dddd, where dddd is one or more decimal digits; the number of digits before the decimal point depends on the magnitude of the number, and the number of digits after the decimal point depends on the requested precision \r\n* g:  Signed value printed in f or e format, whichever is more compact for the given value and precision; trailing zeros are truncated, and the decimal point appears only if one or more digits follow it \r\n* G:  Identical to the g format, except that E, rather than e, introduces the exponent (where appropriate) \r\n"});
        this.addAnnotation((ENamedElement)this.argumentDirectionEnumEEnum, source, new String[]{"documentation", "Use cases:\r\n\r\n* Arguments in ClientServerOperation can have different directions that need to be formally indicated because they have an impact on how the function signature looks like eventually.\r\n\r\n* Arguments in BswModuleEntry already determine a function signature, but the direction is used to specify the semantics, especially of pointer arguments. "});
        this.addAnnotation((ENamedElement)this.argumentDirectionEnumEEnum.getELiterals().get(0), source, new String[]{"documentation", "The argument value is passed to the callee."});
        this.addAnnotation((ENamedElement)this.argumentDirectionEnumEEnum.getELiterals().get(1), source, new String[]{"documentation", "The argument value is passed from the callee  to the caller."});
        this.addAnnotation((ENamedElement)this.argumentDirectionEnumEEnum.getELiterals().get(2), source, new String[]{"documentation", "The argument value is passed to the callee but also passed back from the callee to the caller."});
        this.addAnnotation((ENamedElement)this.nameTokensEDataType, source, new String[]{"documentation", "This is a white-space separated list of name tokens."});
        this.addAnnotation((ENamedElement)this.cIdentifierEDataType, source, new String[]{"documentation", "This datatype represents a string, that follows the rules of C-identifiers."});
        this.addAnnotation((ENamedElement)this.identifierEDataType, source, new String[]{"documentation", "An Identifier is a string with a number of constraints on its appearance, satisfying the requirements typical programming languages define for their Identifiers.\r\n\r\nThis datatype represents a string, that can be used as a c-Identifier.\r\n\r\nIt needs to start with a letter, may consist of letters, digits and underscore. It shall not have two consecutive underscores (to support subsequent name mangling based on \"__\")."});
        this.addAnnotation((ENamedElement)this.refEDataType, source, new String[]{"documentation", "This primitive denotes a name based reference. For detailed syntax see the xsd.pattern.\r\n\r\n* first slash (relative or absolute reference) [optional]\r\n* Identifier  [required]\r\n* a sequence of slashes and Identifiers [optional]\r\n\r\nThis primitive is used by the meta-model tools to create the references."});
        this.addAnnotation((ENamedElement)this.integerContainerEClass.getEOperations().get(0), source, new String[]{"body", "return (<%org.artop.aal.common.datatypes.IntegerDatatype%>)value.clone();"});
        this.addAnnotation((ENamedElement)this.integerContainerEClass.getEOperations().get(1), source, new String[]{"body", "value.setRadix(newValue.getRadix());\nvalue.setNoOfDigits(newValue.getNoOfDigits());\nsetValue(newValue.getValue());\n"});
    }

